// Clean and validate the request. Forgiving about the URL, strict about everything else.
const inItem = $input.first().json;
const b = inItem.body ?? inItem;
const h = inItem.headers ?? {};
const s = (v) => (typeof v === 'string' ? v : '');
const action = b.action;

// Remove our own wrapper tags so page text cannot break out of <page>.
const stripTags = (t) => t.replace(/<\/?page[^>]*>/gi, '');

// Accepts: plain URL, Markdown link, URL inside a sentence, or a bare domain.
const cleanUrl = (value) => {
  let t = s(value)
    .replace(/[\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .trim();

  t = t.replace(/\\([()\[\]_*~<>])/g, '$1');

  const md = t.match(/^\s*\[[^\]]*\]\((https?:\/\/[\s\S]*)\)\s*$/i);
  if (md) t = md[1].trim();
  else if (t.includes('](http')) t = t.slice(t.lastIndexOf('](') + 2);

  const withScheme = t.match(/https?:\/\/[^\s<>"'\x60]+/i);
  if (withScheme) {
    t = withScheme[0];
  } else {
    const bare = t.match(/[a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)+(?::\d+)?(?:[\/?#][^\s<>"'\x60]*)?/i);
    if (bare) t = 'https://' + bare[0];
  }

  const count = (str, ch) => str.split(ch).length - 1;
  while (t.length) {
    const last = t[t.length - 1];
    if (/[.,;:!?'"\]>]/.test(last)) t = t.slice(0, -1);
    else if (last === ')' && count(t, ')') > count(t, '(')) t = t.slice(0, -1);
    else break;
  }
  return t.slice(0, 300);
};

const ipRaw =
  s(h['cf-connecting-ip']) ||
  s(h['x-forwarded-for']).split(',')[0].trim() ||
  s(h['x-real-ip']) ||
  '';

const out = { action, valid: false, ipRaw };

if (action === 'scrape_page') {
  out.url = cleanUrl(b.url);
  out.turnstileToken = s(b.turnstileToken);

  // Email is optional. A bad address is ignored: the page is still read, only the email is skipped.
  const rawEmail = s(b.notifyEmail).trim().toLowerCase();
  const emailOk =
    rawEmail.length > 0 &&
    rawEmail.length <= 254 &&
    /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(rawEmail);
  out.notifyEmail = emailOk ? rawEmail : null;

  out.valid =
    b.source === 'testarosa-playground' &&
    /^https?:\/\/[^\s\/]+\.[^\s\/]+/i.test(out.url);

} else if (action === 'ask_page') {
  out.url = cleanUrl(b.url);
  out.content = stripTags(s(b.content)).slice(0, 60000);
  out.question = s(b.question).trim().slice(0, 300);
  out.history = (Array.isArray(b.history) ? b.history : [])
    .slice(-6)
    .map((x) => ({
      role: x && x.role === 'assistant' ? 'assistant' : 'user',
      text: stripTags(s(x && x.text)).slice(0, 1000)
    }));

  out.valid =
    b.source === 'testarosa-playground' &&
    out.content.length > 0 &&
    out.question.length >= 3;
}

return [{ json: out }];

// Playground rate limit kept in this workflow's own static data.
// Only persists on ACTIVE (production) runs, not manual test runs.
// The caller IP is hashed before it is stored, so no raw address is kept.
const item = $('Clean input').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const K = 'scrape';

const MAX_PER_IP_PER_HOUR = 50;
const MAX_REQUESTS_PER_HOUR = 100;   // whole demo, all visitors
const MAX_EMAILS_PER_ADDRESS_PER_DAY = 50;   // one inbox
const MAX_EMAILS_PER_DAY = 100;              // whole demo

const hash = (str) => {
  let x = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { x ^= str.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
  return x.toString(16);
};
const ipKey = item.ipRaw ? hash('playground|' + item.ipRaw) : null;

sd[K + 'Hits'] = (sd[K + 'Hits'] || []).filter((t) => now - t < HOUR);
sd[K + 'Ip'] = sd[K + 'Ip'] || {};
for (const k of Object.keys(sd[K + 'Ip'])) {
  sd[K + 'Ip'][k] = sd[K + 'Ip'][k].filter((t) => now - t < HOUR);
  if (sd[K + 'Ip'][k].length === 0) delete sd[K + 'Ip'][k];
}
sd.mailAll = (sd.mailAll || []).filter((t) => now - t < DAY);
sd.mailBy = sd.mailBy || {};
for (const k of Object.keys(sd.mailBy)) {
  sd.mailBy[k] = sd.mailBy[k].filter((t) => now - t < DAY);
  if (sd.mailBy[k].length === 0) delete sd.mailBy[k];
}

let allowed = true;
let notifyEmail = item.notifyEmail || null;
const ipList = ipKey ? (sd[K + 'Ip'][ipKey] || []) : [];

if (sd[K + 'Hits'].length >= MAX_REQUESTS_PER_HOUR || ipList.length >= MAX_PER_IP_PER_HOUR) {
  allowed = false;
} else {
  sd[K + 'Hits'].push(now);
  if (ipKey) { ipList.push(now); sd[K + 'Ip'][ipKey] = ipList; }
  if (notifyEmail) {
    const mine = sd.mailBy[notifyEmail] || [];
    if (mine.length >= MAX_EMAILS_PER_ADDRESS_PER_DAY || sd.mailAll.length >= MAX_EMAILS_PER_DAY) {
      notifyEmail = null; // still read the page, just skip the email
    } else {
      mine.push(now);
      sd.mailBy[notifyEmail] = mine;
      sd.mailAll.push(now);
    }
  }
}

const { ipRaw, ...rest } = item; // drop the raw IP from here on
return [{ json: { ...rest, notifyEmail, allowed } }];

// Light address check: the URL is already cleaned in "Clean input".
// This only blocks things that are not a normal public website. No URL class needed.
const raw = String($input.first().json.url || '');
const fail = (error) => [{ json: { ok: false, code: 'blocked_url', error } }];

const m = raw.match(/^(https?):\/\/([^\/?#]*)([^#]*)/i);
if (!m) return fail("That doesn't look like a web address.");

const authority = m[2];
if (authority.includes('@')) return fail('Remove the username and password from the address.');

const hp = authority.match(/^([^:]+)(?::(\d+))?$/);
if (!hp) return fail("That doesn't look like a web address.");

const host = hp[1].toLowerCase().replace(/\.$/, '');
const port = hp[2] || '';
if (port && port !== '80' && port !== '443') return fail('Only the standard web ports are allowed.');

const privateV4 = /^(0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.)/;
if (
  host === 'localhost' ||
  host.endsWith('.local') ||
  host.endsWith('.internal') ||
  privateV4.test(host) ||
  !host.includes('.') ||
  /^[\d.]+$/.test(host)
) {
  return fail('Only public websites can be read, not local or internal addresses.');
}

let rest = m[3] || '/';
if (!rest.startsWith('/')) rest = '/' + rest;
try { rest = encodeURI(rest); } catch (e) { /* keep as is */ }

const origin = m[1].toLowerCase() + '://' + host + (port ? ':' + port : '');
return [{ json: { ok: true, url: origin + rest, origin, host, pathname: rest.split('?')[0], path: rest } }];

// Respect robots.txt: if it disallows this path for everyone, stop.
const { path, url } = $('Vet address').first().json;
const res = $input.first().json;
const body = typeof res.data === 'string' ? res.data : '';

if (res.statusCode >= 200 && res.statusCode < 300 && body) {
  let applies = false;
  for (const line of body.split(/\r?\n/)) {
    const [k, ...rest] = line.split('#')[0].split(':');
    const key = (k || '').trim().toLowerCase();
    const val = rest.join(':').trim();
    if (key === 'user-agent') applies = val === '*';
    else if (applies && key === 'disallow' && val && path.startsWith(val)) {
      return [{ json: { ok: false, code: 'robots_disallowed', error: "That site's robots.txt asks scrapers not to read this page." } }];
    }
  }
}
return [{ json: { ok: true, url } }];

// HTML to plain text. Also decides whether a Google-snippets fallback is worth trying.
const vet = $('Vet address').first().json;
const base = { url: vet.url, host: vet.host, pathname: vet.pathname };
const r = $input.first().json;
const code = r.statusCode;
const html = (typeof r.data === 'string' ? r.data : '').slice(0, 2000000); // 2 MB cap
const fail = (c, error, fallback) => [{ json: { ok: false, code: c, error, fallback, ...base } }];

if (!code) return fail('fetch_failed', 'The site did not answer in time.', true);
if (code >= 300 && code < 400) return fail('fetch_failed', 'That address redirects elsewhere. Enter the final address instead.', false);
if (code < 200 || code >= 300) {
  // blocked / busy / broken sites are worth a try through Google snippets. A plain 404 is not.
  const retry = [401, 403, 429, 451].includes(code) || code >= 500;
  return fail('fetch_failed', 'The site answered with status ' + code + '.', retry);
}

const pick = (re) => (html.match(re)?.[1] || '').replace(/\s+/g, ' ').trim();
const decode = (t) => t
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");

const title = decode(pick(/<title[^>]*>([\s\S]*?)<\/title>/i)).slice(0, 200);
const description = decode(pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i)).slice(0, 300);

const toText = (src) => decode(
  src
    .replace(/<(script|style|noscript|svg|nav|footer|header|form|aside)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|h[1-6]|br|tr)>/gi, '\n')
    .replace(/<\/?[a-z][^>"']*(?:(?:"[^"]*"|'[^']*')[^>"']*)*>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
).replace(/<\/?page[^>]*>/gi, '').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

// Prefer the main article area so the length cap is not spent on menus and sidebars.
const mainHtml = (html.match(/<main[\s\S]*?<\/main>/i) || html.match(/<article[\s\S]*?<\/article>/i) || [html])[0];
let text = toText(mainHtml);
if (text.length < 500) {
  const full = toText(html);
  if (full.length > text.length) text = full;
}

if (text.length < 80) {
  return fail('no_content', 'There was almost no readable text on that page. It may need JavaScript or a login.', true);
}

// Cut the trailing reference material (Wikipedia-style) so the length cap and AI tokens go to the real article.
{
  const tail = /^[ \t]*(references|notes|footnotes|citations|bibliography|sources|further reading|external links|see also)[ \t]*(\[[ \t]*edit[ \t]*\])?[ \t]*$/gim;
  let m;
  while ((m = tail.exec(text)) !== null) {
    if (m.index > 2000 && m.index > text.length * 0.4) { text = text.slice(0, m.index).trim(); break; }
  }
}

const truncated = text.length > 60000;
const content = text.slice(0, 60000);
return [{ json: { ok: true, ...base, title, description, truncated, content, wordCount: content.split(/\s+/).length, via: 'direct' } }];

// Fallback: build page text from Google's result snippets for this address.
// Only runs when the page could not be read directly. Snippets are short, so the summary is shallower.
const pg = $('Page text').first().json;
const res = $input.first().json;
const host = String(pg.host || '').replace(/^www\./, '');
const fail = () => [{ json: { ok: false, code: 'no_content', error: 'That page could not be read, and Google had almost nothing for it either. It may need JavaScript or a login.', url: pg.url } }];

const hostOf = (link) => {
  const m = String(link || '').match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
};

const items = Array.isArray(res.organic_results) ? res.organic_results : [];
const sameSite = items.filter((x) => hostOf(x.link) === host).slice(0, 8);

const clean = (t) => String(t || '').replace(/<\/?page[^>]*>/gi, '').replace(/\s+/g, ' ').trim();
const blocks = sameSite
  .map((x) => [clean(x.title), clean(x.snippet), clean(x.link)].filter(Boolean).join('\n'))
  .filter((b) => b.length > 20);
const content = blocks.join('\n\n').slice(0, 60000);
if (content.length < 80) return fail();

const exact = sameSite.find((x) => String(x.link).replace(/\/$/, '') === String(pg.url).replace(/\/$/, '')) || sameSite[0];
return [{ json: {
  ok: true,
  url: pg.url, host: pg.host, pathname: pg.pathname,
  title: clean(exact.title).slice(0, 200),
  description: '',
  truncated: false,
  content,
  wordCount: content.split(/\s+/).length,
  via: 'search_snippets',
} }];

// Server-side check so garbage never leaves n8n.
const r = $input.first().json.output ?? $input.first().json;
const pg = $('Page ready').first().json;
const ctx = $('Rate limit: scrape').first().json;
const s = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const list = (v, max, len) => (Array.isArray(v) ? v.map((x) => s(x, len)).filter(Boolean).slice(0, max) : []);

if (!r || typeof r.summary !== 'string' || !r.summary.trim()) return [{ json: { ok: false } }];

let summary = s(r.summary, 800);
if (pg.via === 'search_snippets') {
  summary = 'Read from Google search snippets, because the page itself could not be fetched. ' + summary;
}

return [{ json: {
  ok: true,
  result: {
    url: pg.url,
    title: pg.title || '',
    description: pg.description || '',
    wordCount: pg.wordCount,
    truncated: pg.truncated === true,
    summary,
    topics: list(r.topics, 6, 60),
    suggestedQuestions: list(r.suggestedQuestions, 4, 200),
    content: pg.content,
  },
  notifyEmail: ctx.notifyEmail || null,
  via: pg.via || 'direct',
} }];

// Builds the result email. Everything that came from the web page or the model is HTML-escaped.
const d = $input.first().json;
const r = d.result;
const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const h3 = (t) => '<h3 style="font-size:16px;margin:24px 0 4px 0;color:#202124;">' + t + '</h3>';
const ul = (items) => items.length
  ? '<ul style="margin:6px 0 0 0;padding-left:22px;">' + items.map((i) => '<li style="margin:4px 0;">' + esc(i) + '</li>').join('') + '</ul>'
  : '';
const pill = (t) => '<span style="display:inline-block;margin:2px 4px 2px 0;padding:2px 10px;border:1px solid #dadce0;border-radius:999px;font-size:12px;color:#5f6368;">' + esc(t) + '</span>';

const hm = String(r.url || '').match(/^https?:\/\/([^\/?#]+)/i);
const host = hm ? hm[1] : r.url;
const title = r.title || host;
const snippets = d.via === 'search_snippets';

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#202124;max-width:640px;">' +
  '<h2 style="font-size:22px;margin:0 0 4px 0;">' + esc(title) + '</h2>' +
  '<p style="margin:0 0 14px 0;color:#5f6368;font-size:13px;">' + esc(r.url) + '<br>' +
    esc(r.wordCount) + ' words read' + (r.truncated ? ' (long page, cut at 60,000 characters)' : '') +
    (snippets ? ' &nbsp;|&nbsp; via Google search snippets' : '') + '</p>' +
  (r.description ? '<p style="margin:0 0 10px 0;color:#5f6368;">' + esc(r.description) + '</p>' : '') +
  '<p style="margin:0;">' + esc(r.summary) + '</p>' +
  (r.topics.length ? h3('Topics') + '<div style="margin-top:6px;">' + r.topics.map(pill).join('') + '</div>' : '') +
  (r.suggestedQuestions.length ? h3('Questions to ask the bot') + ul(r.suggestedQuestions) : '') +
  '<p style="margin:20px 0 0 0;color:#5f6368;">Go back to the Chatbot Web Scraper page and ask any of these. The bot answers only from this page\'s text and says so when the answer is not on it.</p>' +
  '<hr style="border:none;border-top:1px solid #bdc1c6;margin:28px 0 12px 0;">' +
  '<p style="font-size:12px;color:#80868b;margin:0;">Sent from the Testarosa Playground demo. The summary is AI-generated from the page text and may miss or misread things. Verify before relying on it.</p>' +
  '</div>';

return [{ json: { to: d.notifyEmail, subject: 'Page read: ' + String(title).slice(0, 80), html } }];

// Playground rate limit kept in this workflow's own static data.
// Only persists on ACTIVE (production) runs, not manual test runs.
// The caller IP is hashed before it is stored, so no raw address is kept.
const item = $('Clean input').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const K = 'ask';

const MAX_PER_IP_PER_HOUR = 30;
const MAX_REQUESTS_PER_HOUR = 150;   // whole demo, all visitors

const hash = (str) => {
  let x = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { x ^= str.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
  return x.toString(16);
};
const ipKey = item.ipRaw ? hash('playground|' + item.ipRaw) : null;

sd[K + 'Hits'] = (sd[K + 'Hits'] || []).filter((t) => now - t < HOUR);
sd[K + 'Ip'] = sd[K + 'Ip'] || {};
for (const k of Object.keys(sd[K + 'Ip'])) {
  sd[K + 'Ip'][k] = sd[K + 'Ip'][k].filter((t) => now - t < HOUR);
  if (sd[K + 'Ip'][k].length === 0) delete sd[K + 'Ip'][k];
}

let allowed = true;
let notifyEmail = item.notifyEmail || null;
const ipList = ipKey ? (sd[K + 'Ip'][ipKey] || []) : [];

if (sd[K + 'Hits'].length >= MAX_REQUESTS_PER_HOUR || ipList.length >= MAX_PER_IP_PER_HOUR) {
  allowed = false;
} else {
  sd[K + 'Hits'].push(now);
  if (ipKey) { ipList.push(now); sd[K + 'Ip'][ipKey] = ipList; }
}

const { ipRaw, ...rest } = item; // drop the raw IP from here on
return [{ json: { ...rest, notifyEmail, allowed } }];

// Guard against made-up sources: keep only quotes that really appear on the page.
const r = $input.first().json.output ?? $input.first().json;
const content = $('Clean input').first().json.content || '';
const norm = (t) => String(t || '').replace(/\s+/g, ' ').trim().toLowerCase();
const page = norm(content);

if (!r || typeof r.answer !== 'string' || !r.answer.trim()) return [{ json: { ok: false } }];

const sources = (Array.isArray(r.sources) ? r.sources : [])
  .filter((q) => typeof q === 'string' && q.trim() && page.includes(norm(q)))
  .slice(0, 3)
  .map((q) => q.trim().slice(0, 240));

// If the model claims it found the answer but cannot show where, it did not.
const found = r.found === true && sources.length > 0;
return [{ json: { ok: true, result: { answer: r.answer.trim().slice(0, 1200), found, sources } } }];
